class Service {
  constructor(name, role) {
    this.name = name;
    this.role = role;
  }
  getDetails() {
    return `${this.name} (${this.role})`;
  }
}
const s = new Service('Alice', 'Architect');
const execute = s.getDetails;
console.log(execute());
